SINA_SMART["physics1-states"] = {"lecture":"physics1-states","title":"Physical states of matter","mapStatus":"auto: generated by universal.py from the lecture summary and key points; not human-reviewed","los":[{"id":"physics1-states:e0","text":"State = balance between attraction and dispersion.","topic":"The big picture","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"physics1-states:e4","text":"Repulsion (Pauli) and thermal (Brownian) agitation disperse molecules.","topic":"The big picture","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"physics1-states:e1","text":"Coulomb: F = kqq′/(εd²); water ε = 78.5 → ions dissociate.","topic":"Intermolecular forces","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"physics1-states:e2","text":"Van der Waals: dipole forces, very short range.","topic":"Intermolecular forces","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"physics1-states:e3","text":"Solvation (hydration in water): ions surrounded by solvent dipoles.","topic":"Intermolecular forces","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"physics1-states:e5","text":"Solid ordered and fixed; liquid fixed volume, flows; gas compressible.","topic":"Intermolecular forces","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"physics1-states:e6","text":"Melting and freezing at constant temperature; supercooling possible.","topic":"Changes of state","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"physics1-states:e7","text":"Cryoscopy: Δθ = 1.86 × osmolality (water); plasma ≈ −0.56 °C.","topic":"Changes of state","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"physics1-states:e8","text":"Water evaporation cools the body (latent heat).","topic":"Changes of state","sec":2,"importance":"core","highYield":"insufficient-source"}],"vmap":{},"mlevel":{"stdmxi":"a","1eynzr7":"a","1ki50bz":"a","15jjy72":"a","sccggp":"a","1oziw5f":"a","6fb49s":"a","kk5mao":"a","17mcask":"a","1o0le1l":"a","1x1bvgk":"a","jx2522":"a","x0irzv":"a","l68f6a":"a"},"mapCounts":{"verified":0,"auto":14,"ambiguous":0,"missing":0},"mrules":[],"items":[],"experimental":[],"status":{},"difficulty":{},"expl":{"physics1-states:e0":{"s":0,"u":["State = balance between attraction and dispersion.","The molecules are the same in each state; what differs is the balance between attractive forces that gather particles and repulsive causes (repulsion, thermal agitation) that disperse them."],"dp":[]},"physics1-states:e4":{"s":0,"u":["Repulsion (Pauli) and thermal (Brownian) agitation disperse molecules.","The molecules are the same in each state; what differs is the balance between attractive forces that gather particles and repulsive causes (repulsion, thermal agitation) that disperse them."],"dp":[]},"physics1-states:e1":{"s":1,"u":["Coulomb: F = kqq′/(εd²); water ε = 78.5 → ions dissociate.","Between ions : Coulomb's law F = k·q·q′/(ε·d²) : inversely proportional to the dielectric constant ε and to distance squared.","Water has a high ε ( 78.5 at 25 °C), so ions attract weakly and separate: electrolytic dissociation ; ethanol (ε = 24.3) keeps ions together."],"dp":[]},"physics1-states:e2":{"s":1,"u":["Van der Waals: dipole forces, very short range.","Between neutral molecules : Van der Waals forces from uneven charge distribution (dipoles), very short-range (F ∝ 1/r⁷)."],"dp":[]},"physics1-states:e3":{"s":1,"u":["Solvation (hydration in water): ions surrounded by solvent dipoles.","Ion-dipole : ions attract the opposite pole of solvent dipoles: solvation (in water, hydration ; Na⁺ surrounded by the oxygen poles of water).","Water has a high ε ( 78.5 at 25 °C), so ions attract weakly and separate: electrolytic dissociation ; ethanol (ε = 24.3) keeps ions together."],"dp":[]},"physics1-states:e5":{"s":1,"u":["Solid ordered and fixed; liquid fixed volume, flows; gas compressible.","Solid : ordered, dense, fixed shape and volume.","Liquid : disordered but close molecules, dense, takes the container's shape, fixed volume."],"dp":[]},"physics1-states:e6":{"s":2,"u":["Melting and freezing at constant temperature; supercooling possible.","Freezing : a liquid can cool below its freezing point without solidifying ( supercooling / superfusion ), then jumps back to the freezing temperature as it solidifies.","Melting (solid → liquid): during the change, temperature stays constant (0 °C for water at 1 atm) while solid and liquid coexist."],"dp":[]},"physics1-states:e7":{"s":2,"u":["Cryoscopy: Δθ = 1.86 × osmolality (water); plasma ≈ −0.56 °C.","Cryoscopy : a solution freezes at a lower temperature than its solvent; the cryoscopic depression Δθ = K × osmolality (Raoult's law), with K = 1.86 °C·kg/mol for water (plasma ≈ water).","Measuring Δθ gives a fluid's osmolality (plasma freezes at about −0.56 °C)."],"dp":[{"h":"Why cryoscopy measures osmolality","t":"Dissolved particles make it harder for solvent molecules to organise into a crystal, lowering the freezing point in proportion to the number of particles per kilogram of solvent, whatever their nature. Measuring how far below 0 °C plasma or urine freezes therefore counts all its dissolved particles, which is how osmometers work in the lab. Source: the lecture's freezing and Raoult's law slides."}]},"physics1-states:e8":{"s":2,"u":["Water evaporation cools the body (latent heat).","Thermoregulation : evaporating water (sweat, breath) absorbs large amounts of heat (latent heat), the body's main way to lose heat when the environment is hot."],"dp":[]}},"meta":{"stdmxi":{"a":"recall","vg":"physics1-states:e0/recall/1"},"1eynzr7":{"a":"relationship","vg":"physics1-states:e1/relationship/1"},"1ki50bz":{"a":"relationship","vg":"physics1-states:e1/relationship/2"},"15jjy72":{"a":"relationship","vg":"physics1-states:e2/relationship/1"},"sccggp":{"a":"recall","vg":"physics1-states:e3/recall/1"},"1oziw5f":{"a":"relationship","vg":"physics1-states:e4/relationship/1"},"6fb49s":{"a":"recall","vg":"physics1-states:e5/recall/1"},"kk5mao":{"a":"recall","vg":"physics1-states:e5/recall/2"},"17mcask":{"a":"recall","vg":"physics1-states:e6/recall/1"},"1o0le1l":{"a":"recall","vg":"physics1-states:e6/recall/2"},"1x1bvgk":{"a":"recall","vg":"physics1-states:e7/recall/1"},"jx2522":{"a":"recall","vg":"physics1-states:e7/recall/2"},"x0irzv":{"a":"recall","vg":"physics1-states:e5/recall/3"},"l68f6a":{"a":"recall","vg":"physics1-states:e8/recall/1"}},"explRev":"cafa6105f754"};
